/// `UBFM_64M_bitfield`.
///
/// Cut: DecodeBitMasks, X_read, X_set.
pub(super) fn UBFM_64M_bitfield(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::UBFM_64M_bitfield;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let s1: u128 = (w >> 0) & 0x1f;
    let s2: u128 = (w >> 5) & 0x1f;
    let s3: u128 = (w >> 10) & 0x3f;
    let s4: u128 = (w >> 16) & 0x3f;
    let s5: i128 = s1 as i128;
    let s6: i128 = s2 as i128;
    let s7: i128 = s4 as i128;
    let (s9w, s9t, s9ok) = rt::decode_bit_masks(0x1u128, s3, s4, false, 64);
    if !s9ok {
        return Err(LiftError::Undefined(ENC));
    }
    let v10 = st.x_read(b, s6 as u32, 64);
    let s11: u128 = !s9w & 0xffffffffffffffff;
    let s12: u128 = 0x0u128 & s11;
    let s13: bool = s7 == (0i128);
    let s15: i128 = rt::fmod(s7, (64i128));
    let v16 = b.konst(Width::new(128), (s15) as u128);
    let v17 = b.bin(BinOp::LShr, v10, v16);
    let s18: i128 = (64i128).wrapping_sub(s15);
    let v19 = b.konst(Width::new(128), (s18) as u128);
    let v20 = b.bin(BinOp::Shl, v10, v19);
    let v21 = b.bin(BinOp::Or, v17, v20);
    let v22 = if s13 { v10 } else { v21 };
    let v23 = b.konst(Width::new(64), s9w);
    let v24 = b.bin(BinOp::And, v22, v23);
    let v25 = b.konst(Width::new(64), s12);
    let v26 = b.bin(BinOp::Or, v25, v24);
    let s27: u128 = !s9t & 0xffffffffffffffff;
    let s28: u128 = 0x0u128 & s27;
    let v29 = b.konst(Width::new(64), s9t);
    let v30 = b.bin(BinOp::And, v26, v29);
    let v31 = b.konst(Width::new(64), s28);
    let v32 = b.bin(BinOp::Or, v31, v30);
    st.x_set(b, s5 as u32, v32, None);
    Ok(())
}

